Q: Calling the Oracle function from Oledb Connection
A: <p>When you execute a <code>Stored Procedure</code> with ado.net, you must set the <a href="http://msdn.microsoft.com/library/system.data.common.dbcommand.commandtype(v=vs.110).aspx" rel="nofollow"><code>CommandType</code></a> property from your <code>IDbCommand</code> object to <a href="http://msdn.microsoft.com/library/system.data.commandtype(v=vs.110).aspx" rel="nofollow"><code>CommandType.StoredProcedure</code></a>. For sample:</p>

<pre><code>using (OleDbConnection conn= new OleDbConnection(connectionString))
{
    conn.Open();

    // set the commend type here    
    command.CommandType = CommandType.StoredProcedure;

    //set the command text (stored procedure name or SQL statement)
    command.CommandText = "VOD_BULK_TRANS1";

    command.Parameters.Add(new OleDbParameter("retVal", OleDbType.VarChar, 11, ParameterDirection.ReturnValue, true, 0, 0, "retVal", DataRowVersion.Current,null));
    command.Parameters.Add( OleDbParameter("@t_list", videosListWithCommaSeparated);
    command.Parameters.Add( OleDbParameter("@option1", 3);
    command.Parameters.Add( OleDbParameter("@id1", groupId);
    command.ExecuteNonQuery();

}
</code></pre>

