Q: How to quickly load and display images with WPF/BitmapImage?
A: <p>If you cannot use prepared preview (downscaled) images, at least do not render image at it's full size. To avoid doing that, use <code>DecodePixelWidth</code> (or <code>DecodePixelHeight</code>) property. Set it to some reasonable value (maybe based on current monitor resolution), and you will already see significant perfomance improvement:</p>

<pre><code>public class FilenameToImageConverter : IValueConverter {
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture) {
        string uri = value as string;

        if (uri != null &amp;&amp; File.Exists(uri)) {
            BitmapImage image = new BitmapImage();
            image.BeginInit();
            image.CacheOption = BitmapCacheOption.OnLoad;
            image.UriSource = new Uri(uri);
            image.DecodePixelWidth = 1920; // should be enough, but you can experiment
            image.EndInit();
            return image;
        }

        return null;
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) {
        throw new NotSupportedException();
    }
}
</code></pre>

