  fprintf(stderr, "out of memory\n");
  return;
} 
// Use c
(*c)[1][2] = rand();
...
free(c);
</code></pre>

<p>Without VLA support, if the dimensions are constants, code can use</p>

<pre><code>#define NROW 4
#define NCOL 5
int (*d)[NROW][NCOL] = malloc(sizeof *d);
</code></pre>

