Q: Create Access Table from SQLDataReader
A: <p>This is my "final solution". The comments suggesting using a linked server certainly would have been an easier approach, but there was one thing preventing me from doing that which didn't occur to me at first, the data needs to exist in the Access DB as the users may consume the data away from where they would have network access to the underlying DB. As such, I kept banging away at this approach and here's what I came up with:</p>

<p>Note that I'd still be open to suggestions for a "better way", but this solves my current problem </p>

<pre><code>static void CreateTableFromReader(string tableName, SqlDataReader reader) {
  List&lt;string&gt; columns = new List&lt;string&gt;();
  string createTable = @"CREATE TABLE {0} ({1})";

  var dt = reader.GetSchemaTable();
  foreach (DataRow dr in dt.Rows) {
    switch (dr["DataTypeName"].ToString().ToLower()) {
      case "varchar":
        columns.Add(String.Format("[{0}] {1}({2})",
          dr["ColumnName"],
          dr["DataTypeName"],
          dr["ColumnSize"]
        ));
        break;
      case "money": //i know this is redundant but being explicit helps clarity sometimes
      case "date":
      case "integer":
      default:
        columns.Add(String.Format("[{0}] {1}",
          dr["ColumnName"],
          dr["DataTypeName"]
        ));
        break;
    }
  }
  using (var cmd = conn_Access.CreateCommand()) {
    cmd.CommandType = CommandType.Text;
    cmd.CommandText = String.Format(createTable, tableName, String.Join(", ", columns));
    cmd.ExecuteNonQuery();
  }
}
</code></pre>

