Q: Typeahead + Bloodhound - Have to enter additional character to see data source change
A: <p>I faced two different problems while trying to find a solution:</p>

<ol>
<li>the latest typeahead version seems to be less stable than the previous version 0.10.2 (and the Original twitter project is considered dead, some community forks exist and are maintained).</li>
<li>a bound data source does not react to updates properly.</li>
</ol>

<p>What I changed:</p>

<ol>
<li>Switched to <a href="http://cdnjs.cloudflare.com/ajax/libs/typeahead.js/0.10.2/typeahead.bundle.min.js" rel="nofollow noreferrer">the 0.10.2 typeahead bundle</a>.</li>
<li>manually added Bloodhound search result.</li>
</ol>

<h2>Updated code:</h2>

<pre><code>var filter = function(suggestions) {
  return $.grep(suggestions, function(suggestion) {
    return -1;
  });
}

var titles = new Bloodhound({
  name: 'titles',
  datumTokenizer: function(data) {
    return Bloodhound.tokenizers.whitespace(data.label);
  },
  queryTokenizer: Bloodhound.tokenizers.whitespace,
  local: data1
});
titles.initialize();

$('#search-input').typeahead({
  highlight: true
}, {
  name: 'titles',
  displayKey: 'label',
  source: function(query, callbackFunc) {
    titles.clear();

    if ($('#search-input').val().length &gt; 2) {
      titles.local = data2;
      sourceSelected.text('Data Source 2');
    } else {
      titles.local = data1;
      sourceSelected.text('Data Source 1');
    }

    titles.initialize(true);
    titles.get(query, function(suggestions) {
      callbackFunc(filter(suggestions));
    });
  }
});
</code></pre

Q: Limit html text input to a particular number of bytes?
A: <p>this script has a couple minor UX glitches that can be cleaned up, but it does accomplish the basic task outlined when i tested it in chrome:</p>

<pre><code>&lt;input id=myinp /&gt;


&lt;script&gt; // bind handlers to input:
   myinp.onkeypress=myinp.onblur=myinp.onpaste= function vld(e){
     var inp=e.target;
     // count bytes used in text:
     if( encodeURIComponent(inp.value).replace(/%[A-F\d]{2,6}/g, 'U').length &gt; 4){
        // if too many bytes, try to reject:
        e.preventDefault;
        inp.value=inp.val||inp.value;
        return false;
     }
     // backup last known good value:
    inp.val=inp.value;
   }

&lt;/script&gt;
</code></pre>

