Q: download xls/xlsx file from google drive api
A: <h2 id="the-files.export-method-as-used-in-the-documentation-sample-can-only-be-used-for-downloading-google-workspace-documents">The <a href="https://developers.google.com/drive/api/v3/reference/files/export" rel="nofollow noreferrer">files.export</a> method as used in the <a href="https://developers.google.com/drive/api/v3/manage-downloads#download_a_document" rel="nofollow noreferrer">documentation sample</a> can only be used for downloading Google Workspace documents</h2>
<p>For downloading non-Google Workspace documents you need to use the <a href="https://developers.google.com/drive/api/v3/reference/files/get" rel="nofollow noreferrer">files.get</a> method as in the <a href="https://developers.google.com/drive/api/v3/manage-downloads#download_a_file_stored_on_google_drive" rel="nofollow noreferrer">sample for Download a file stored on Google Drive</a>:</p>
<pre class="lang-js prettyprint-override"><code>export function getFileFromStream(auth, fileId, mimeType) {
  const destPath = `/tmp/${fileId}.xls`;
  const dest = fs.createWriteStream(destPath);
  return new Promise(async (resolve, reject) =&gt; {
    const drive = google.drive({version: 'v3', auth});
    drive.files.get({
      fileId: fileId,
      alt: 'media'
    })
      .on('end', function () {
        console.log('Done');
      })
      .on('error', function (err) {
        console.log('Error during download', err);
      })
    .pipe(dest);
}
</code></pre>

