Q: How can I incorporate a child/parent relationship into a sort function?
A: <p>It might not be the most efficient way, so it is a good solution if you don't have a lot of events.</p>

<p>The JS without the object:</p>

<pre><code> var newEvents = [];
 var childEvents = [];
 var parentEvents = [];

 $.each(events, function (i, e) {
     e.start = new Date(e.start);
     if (e.end) {
         e.end = new Date(e.end);
     }
 });

 events.sort(function (a, b) {
     return a.start - b.start;
 });

 $.each(events, function (i, e) {
     if (e.parentId) {
         childEvents.push(e);
     } else {
         parentEvents.push(e);
     }
 });

 $.each(parentEvents, function (i, e) {
     newEvents.push(e);
     $.each(childEvents, function (childIndex, child) {
         if (child.parentId == e.id) {
             newEvents.push(child);
         }
     });
 });


 $.each(newEvents, function (i, e) {
     console.log(e.content);
 });
</code></pre>

<p><a href="http://fiddle.jshell.net/c3Lwsu32/7/" rel="nofollow">Fiddle example</a></p>

<p>Another approach you can add relationship to the way the object is build- you can create the child events as a property of the parent, and then you can sort Parent/children:</p>

<pre><code>var addRelationships = function(){
    $.each(events,function(i,e){
        if(e.parentId){
            for(var i=0;i&lt;events.length;i++){
                var parent = events[i];

                if(parent.id == e.parentId){
                    e.parent = parent;
                }

                if(!parent.children){
